// 「作者是对着**变量**做能力检测，不是对着服务名」。
//
// 背景（实测 20 处真实命中）：
//   const s = ctx.get("jobs");
//   if (typeof s.noSuchMethod !== "function") return;
//   s.noSuchMethod();
//
// 调用点的归属是 `jobs`，但源码里根本没有 `jobs.noSuchMethod` 这几个字 ——
// 只有 `s.noSuchMethod`。只看服务名就认不出兜底，于是报一条**假阳性**，
// 而被冤枉的作者明明写得比大多数人都仔细。
//
// 期望：判定为「可用」，且 `jobs.noSuchMethod` **不得**出现在发现里。
export function apply(ctx) {
  const s = ctx.get('jobs');
  if (typeof s.noSuchMethod !== 'function') return;
  s.noSuchMethod();
}
